tool.command:
mkdir -p partitions &&
for i in $input_cluster; do
    name=$i.element_identifier;
    number=$(echo $name | rev | cut -d'_' -f1 | tr -d '.fasta');
    fullpath=selected_cluster/cluster${number};
    mkdir -p $fullpath &&
    ln -s $i $fullpath/2_all_seqs.fasta;
done &&
trycycler partition --cluster_dir selected_cluster/cluster_* \
    --reads $reads \
    --min_aligned_len $min_aligned_len \
    --min_read_cov $min_read_cov \
    --threads \${GALAXY_SLOTS:-2} &&
for i in $input_cluster; do
    name=$i.element_identifier;
    number=$(echo $name | rev | cut -d'_' -f1 | tr -d '.fasta');
    mv selected_cluster/cluster${number}/4_reads.fastq partitions/partition_${number}.fastq;
done

tool.help:
**What it does**

Assign reads to clusters generated by Trycycler.

@PIPELINE@
